using System.Text.Json;

namespace KlikerBlocks;

// Offline FR/ES/ZH topic and block guidance. Full Russian reference remains available
// through local Argos translation when a ru→target model is installed.
internal static class LocalizedHelp
{
    private static readonly Dictionary<string, string[]> Topics = Parse(TopicData);
    private static readonly Dictionary<string, string[]> Blocks = Parse(BlockData);
    private sealed class GermanPack
    {
        public string Overview { get; set; } = "";
        public Dictionary<string, string> Sections { get; set; } = [];
        public Dictionary<string, string> Blocks { get; set; } = [];
    }
    private static readonly Lazy<GermanPack?> German = new(() =>
    {
        try
        {
            var path = Path.Combine(AppContext.BaseDirectory, "Languages", "de-help.json");
            return JsonSerializer.Deserialize<GermanPack>(File.ReadAllText(path),
                new JsonSerializerOptions { PropertyNameCaseInsensitive = true });
        }
        catch (Exception error) when (error is IOException or JsonException) { return null; }
    });

    public static string? GermanOverview => German.Value?.Overview;

    public static string? Section(string title, string language)
    {
        if (language == "de") return German.Value?.Sections.GetValueOrDefault(title);
        if (title == "Демонстрация Что я умею" && language is "fr" or "es" or "zh") return language switch
        {
            "fr" => "La démo saisit et vérifie votre phrase dans le Bloc-notes. La traduction nécessite encore un modèle Argos local. Après huit secondes sans réponse, Paint tente de dessiner une flèche à la souris ; dix secondes plus tard, un autre Bloc-notes rappelle la question. La figure choisie est dessinée à la souris sur le canevas blanc détecté de Paint. Kliker Blocks recherche le crayon dans l’interface moderne ou classique et vérifie que des traits apparaissent. En cas d’échec, la démo signale une erreur. Chaque nouvelle version propose de nouveau la démo ; toute action sur le bureau exige votre accord. Les fichiers et fenêtres restent après l’arrêt.",
            "es" => "La demo escribe y verifica su frase en Bloc de notas. La traducción aún requiere un modelo Argos local. Tras ocho segundos sin respuesta, Paint intenta dibujar una flecha con el ratón; diez segundos después otro Bloc de notas recuerda la pregunta. La figura elegida se dibuja con el ratón sobre el lienzo blanco detectado. Kliker Blocks busca el lápiz en la interfaz moderna o clásica y confirma que aparecieron trazos. Si falla, informa del error. Cada nueva versión vuelve a ofrecer la demo; cualquier acción de escritorio requiere permiso. Los archivos y ventanas permanecen tras detenerla.",
            _ => "演示会在记事本中输入并核对您的短语。翻译仍需本地 Argos 模型。八秒无回答时，画图尝试用鼠标画出提示箭头；再过十秒，另一个记事本提醒回答。所选图形在检测到的白色画布上逐笔绘制。Kliker Blocks 在新版或经典界面查找铅笔并确认画布出现笔迹。失败时会报告错误。每个新版本都会重新提供演示；桌面操作仍需用户同意。停止后窗口和文件保留。"
        };
        if (title == "Окна и точность демонстрации" && language is "fr" or "es" or "zh") return language switch
        {
            "fr" => "Kliker Blocks vérifie tout le document du Bloc-notes, puis corrige les caractères manquants via le presse-papiers. Paint s’ouvre avec un canevas vide ; le crayon, la couleur rouge et les limites visibles du canevas sont détectés avant le dessin à la souris. L’absence de traits est une erreur. La version classique de Paint n’était pas disponible pour un essai réel sur cet ordinateur.",
            "es" => "Kliker Blocks verifica todo el documento de Bloc de notas y corrige los caracteres omitidos mediante el portapapeles. Paint se abre con el lienzo vacío; se detectan el lápiz, el color rojo y los límites visibles antes de dibujar con el ratón. La ausencia de trazos es un error. La versión clásica de Paint no estaba disponible para una prueba real en este equipo.",
            _ => "Kliker Blocks 核对记事本全文，并通过剪贴板修正漏字。画图打开空白画布；绘制前检测铅笔、红色和可见画布边界。没有出现笔迹会被视为错误。本机没有经典版画图，因此未进行该版本的真实界面测试。"
        };
        if (title == "Демонстрация Что я умею") return language switch
        {
            "fr" => "Le menu Ce que je sais faire ouvre un graphe interactif. Le Bloc-notes saisit votre phrase russe ; Kliker Blocks vérifie le document entier via le presse-papiers, y compris les lignes visuellement renvoyées. Un modèle local Argos ru → langue choisie permet la traduction et éventuellement la lecture vocale. Sans modèle, aucune traduction n’est simulée : le Bloc-notes et le rapport expliquent comment installer la paire dans Langues. Choisissez étoile, cœur ou maison. Sans réponse après 8 secondes, une flèche PNG s’ouvre dans Paint ; après 10 autres secondes un rappel apparaît. La forme choisie est enregistrée en PNG puis ouverte dans Paint quel que soit l’outil actif. Kliker Blocks capture la zone, calcule CRC32 et crée un rapport dans Showcase. Le premier lancement propose la démo une fois ; toute action sur le bureau exige votre accord. Arrêt ou Échap interrompt la suite. Fenêtres, fichiers et presse-papiers restent modifiés.",
            "es" => "Lo que puedo hacer abre un grafo interactivo. Bloc de notas escribe su frase rusa; Kliker Blocks verifica el documento completo mediante el portapapeles, incluso las líneas ajustadas visualmente. Un modelo local Argos ru → idioma elegido permite traducir y, si hay voz, leer el resultado. Sin modelo no se finge la traducción: Bloc de notas y el informe explican cómo instalar el par desde Idiomas. Elija estrella, corazón o casa. Tras 8 segundos sin respuesta, una flecha PNG se abre en Paint; tras otros 10 segundos aparece un recordatorio. La figura elegida se guarda en PNG y se abre en Paint sin depender de su herramienta activa. Kliker Blocks captura la zona, calcula CRC32 y crea un informe en Showcase. El primer inicio ofrece la demo una sola vez; las acciones requieren consentimiento. Detener o Esc interrumpe la secuencia; ventanas, archivos y portapapeles permanecen modificados.",
            "zh" => "“我的功能”打开互动图表。记事本输入您的俄语句子；Kliker Blocks 通过剪贴板核对全文，包括视觉上的自动换行。安装对应的本地 Argos 俄语→目标语言模型后才能翻译，并可用匹配的 Windows 语音朗读。若无模型，不会伪装已翻译：记事本和报告会提示到“语言”菜单安装。请选择星形、爱心或房子。8 秒无回答时，画图打开箭头 PNG；再过 10 秒显示提醒。所选形状保存为 PNG 并在画图中打开，不受当前工具影响。Kliker Blocks 截取区域、计算 CRC32，并在 Showcase 文件夹创建报告。首次启动只提供一次演示；桌面操作须经同意。停止或 Esc 会中断后续操作，已打开的窗口、文件和剪贴板更改会保留。",
            _ => Get(Topics, title, language)
        };
        if (title == "Окна и точность демонстрации") return language switch
        {
            "fr" => "Le Bloc-notes est placé à gauche du graphe si l’écran le permet. Tout le document est copié et vérifié ; un retour automatique à la ligne ne duplique plus la phrase. En cas de caractères manquants, le document entier est remplacé par une insertion exacte puis revérifié. La démo s’arrête si le contenu reste incorrect. Le presse-papiers peut ensuite contenir le texte complet. Paint ouvre un PNG préparé, indépendamment du pinceau actif.",
            "es" => "Bloc de notas se sitúa a la izquierda del grafo si hay espacio. Se copia y verifica todo el documento; el ajuste visual de línea no duplica la frase. Si faltan caracteres, se sustituye el documento completo por un texto exacto y se verifica otra vez. La demo se detiene si sigue siendo incorrecto. El portapapeles puede conservar el texto completo. Paint abre un PNG preparado, independientemente del pincel activo.",
            "zh" => "屏幕空间足够时，记事本放在图表左侧。Kliker Blocks 复制并验证全文；视觉自动换行不会重复句子。若漏字，则通过剪贴板替换全文并再次验证；仍不正确时演示会停止。之后剪贴板可能保留全文。画图打开预先生成的 PNG，不依赖当前画笔。",
            _ => Get(Topics, title, language)
        };
        var summary = Get(Topics, title, language);
        if (summary is null || title != "Коды клавиш VK (1–255)") return summary;
        var previous = UiLanguage.Code;
        if (previous != language) return summary;
        return summary + "\n\n" + string.Join("\n", VirtualKeyCatalog.AllCodes()
            .Select(item => $"{item.Code,3}   0x{item.Code:X2}   {VirtualKeyCatalog.DescribeLocalized(item.Code)}"));
    }
    public static string? Block(string kind, string language) => language == "de"
        ? German.Value?.Blocks.GetValueOrDefault(kind) : Get(Blocks, kind, language);

    private static string? Get(Dictionary<string, string[]> values, string key, string language)
    {
        var index = language switch { "fr" => 0, "es" => 1, "zh" => 2, _ => -1 };
        return index >= 0 && values.TryGetValue(key, out var row) ? row[index] : null;
    }

    private static Dictionary<string, string[]> Parse(string data)
    {
        var result = new Dictionary<string, string[]>(StringComparer.Ordinal);
        foreach (var line in data.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries))
        {
            var columns = line.Split('|');
            if (columns.Length != 4 || !result.TryAdd(columns[0], columns[1..]))
                throw new InvalidOperationException("Invalid localized help row: " + line);
        }
        return result;
    }

    private const string TopicData = """
Окна и точность демонстрации|Si l’écran le permet, la démo place le Bloc-notes à gauche et le graphe à droite. Les questions s’ouvrent à droite au-dessus des fenêtres ; sur un écran étroit, un chevauchement est inévitable. Le texte est saisi lentement, puis le contenu réel du Bloc-notes est copié et vérifié. En cas de caractères perdus, la sélection est remplacée par une insertion exacte depuis le presse-papiers et revérifiée. La phrase de l’utilisateur est également copiée et contrôlée avant traduction. Si elle reste différente, la démo s’arrête plutôt que d’inventer un résultat. Le presse-papiers peut conserver la dernière phrase copiée.|Cuando hay espacio, la demo coloca Bloc de notas a la izquierda y el grafo a la derecha. Las preguntas aparecen a la derecha por encima de otras ventanas; en pantallas estrechas no se puede evitar el solapamiento. El texto se escribe despacio y luego se copia y verifica el contenido real de Bloc de notas. Si faltan caracteres, se sustituye la selección con una inserción exacta del portapapeles y se comprueba de nuevo. La frase del usuario también se copia y verifica antes de traducir. Si sigue siendo distinta, la demo se detiene en vez de inventar una traducción. El portapapeles puede conservar la última frase copiada.|屏幕空间允许时，演示将记事本放在左侧、图表放在右侧。输入对话框显示在右侧其他窗口之上；窄屏幕上可能无法避免重叠。文字逐字缓慢输入，然后复制并核对记事本中的实际内容。若有漏字，则通过剪贴板准确替换选中文本并再次核对。用户句子在翻译前也会复制和核对。如仍不一致，演示会停止，不会伪造译文。剪贴板可能保留最后复制的句子。
Демонстрация Что я умею|Le menu Ce que je sais faire ouvre un graphe interactif. Le Bloc-notes saisit et copie votre phrase russe. Si un modèle local Argos ru → langue choisie est installé, il la traduit et peut la lire avec une voix Windows adaptée ; sinon cette étape est signalée comme indisponible. Une question demande de choisir étoile, cœur ou maison. Après 8 secondes sans réponse, Paint essaie de dessiner une flèche vers la question ; 10 secondes plus tard un second Bloc-notes rappelle de répondre. La réponse annule les rappels suivants. Paint dessine la forme, Kliker Blocks capture la zone, calcule un CRC32, enregistre un PNG et ajoute un rapport texte dans le dossier Showcase indiqué par le journal. Le premier lancement propose la démo une seule fois, mais les actions sur le bureau exigent votre accord. Arrêt ou Échap interrompt la suite ; les fenêtres et fichiers restent ouverts et le presse-papiers a changé. Le graphe peut être enregistré au format .klb. Ne l’exécutez pas sur des données sensibles.|El menú Lo que puedo hacer abre un grafo interactivo. Bloc de notas escribe y copia su frase rusa. Si hay un modelo local Argos ru → idioma elegido, la traduce y quizá la lea con una voz de Windows adecuada; si falta, informa de ello. Se pregunta si dibujar estrella, corazón o casa. Tras 8 segundos sin respuesta, Paint intenta dibujar una flecha hacia la pregunta; 10 segundos después aparece otro Bloc de notas recordatorio. Responder cancela los recordatorios posteriores. Paint dibuja la figura, Kliker Blocks captura la zona, calcula CRC32, guarda PNG y añade un informe de texto en la carpeta Showcase indicada en el registro. En el primer inicio se ofrece una sola vez, pero las acciones de escritorio requieren consentimiento. Detener o Esc interrumpe la secuencia; ventanas y archivos permanecen y el portapapeles cambia. Puede guardar el grafo .klb. No lo ejecute sobre datos sensibles.|“我的功能”菜单打开互动图表。记事本输入并复制您的俄语句子。若已安装对应的本地 Argos ru → 目标语言模型，则会翻译并可用匹配的 Windows 语音朗读；否则如实提示缺少模型。随后询问要画星形、爱心还是房子。8 秒无回答时，画图尝试绘制指向问题的箭头；再过 10 秒，另一个记事本显示提醒。回答后取消后续提醒。画图绘制形状，Kliker Blocks 捕获区域、计算 CRC32、保存 PNG，并在日志注明的 Showcase 文件夹追加文字报告。首次启动仅显示一次，但桌面操作需明确同意。停止或 Esc 会中断后续操作；窗口和文件仍保留，剪贴板可能已更改。可将图表保存为 .klb。请勿在敏感信息前运行。
Панель, пауза и трей|Fermer l’éditeur ouvre le panneau compact : démarrer, mettre en pause, reprendre, arrêter ou rouvrir l’éditeur. Fermer ce panneau le masque dans la zone système ; utilisez Quitter Kliker Blocks pour terminer. Chaque instance a sa propre icône : vert = actif, jaune = pause, gris = prêt. La pause attend la fin de l’action en cours.|Al cerrar el editor aparece el panel compacto: iniciar, pausar, reanudar, detener o volver al editor. Cerrar el panel lo oculta en la bandeja; use Salir de Kliker Blocks para terminar. Cada instancia tiene su icono: verde = ejecutando, amarillo = pausa, gris = listo. La pausa espera a que termine la acción actual.|关闭编辑器会打开紧凑控制面板，可运行、暂停、继续、停止或返回编辑器。关闭面板会将其隐藏到系统托盘；选择“退出 Kliker Blocks”才会真正退出。各实例有独立图标：绿色运行、黄色暂停、灰色就绪。暂停会等待当前操作完成。
Запуск и остановка|Un scénario commence par un seul bloc Début. Choisissez un passage ou une répétition jusqu’à l’arrêt. Lancez-le depuis le menu Scénario, le panneau, la zone système ou Ctrl+Alt+F6 ; arrêtez-le avec Ctrl+Alt+F7. Une sortie non reliée termine la branche ; un lien de retour forme une boucle.|Un escenario comienza en un único bloque Inicio. Elija una pasada o repetición hasta detener. Inicie desde Escenario, el panel, la bandeja o Ctrl+Alt+F6; detenga con Ctrl+Alt+F7. Una salida sin enlace termina su rama; un enlace hacia atrás crea un bucle.|场景从唯一的“开始”块运行。可选单次执行或持续重复。通过“场景”菜单、控制面板、托盘或 Ctrl+Alt+F6 启动；用 Ctrl+Alt+F7 停止。未连接的输出会结束分支；反向连接会形成循环。
Визуальные блоки и связи|Ajoutez des blocs depuis la palette. Glissez une sortie vers l’entrée suivante : une sortie n’a qu’un lien, une entrée peut en recevoir plusieurs. Maj+clic gauche sélectionne une zone, Ctrl+C/V copie-colle, Suppr efface un bloc ou lien. Glissez le fond pour déplacer la vue ; Ctrl+molette change le zoom. Les propriétés sont à droite.|Añada bloques desde la paleta. Arrastre una salida a la entrada siguiente: una salida tiene un enlace y una entrada admite varios. Mayús+clic izquierdo selecciona un área; Ctrl+C/V copia y pega; Supr elimina bloque o enlace. Arrastre el fondo para desplazar y Ctrl+rueda para ampliar. Las propiedades están a la derecha.|从左侧面板添加块。将输出端拖到下一块的输入端：一个输出只能连一条线，一个输入可接多条线。Shift+左键框选，Ctrl+C/V 复制粘贴，Delete 删除块或连线。拖动空白处平移，Ctrl+滚轮缩放；右侧编辑属性。
Текстовый код Kliker Blocks|Les onglets Blocs et Code Kliker Blocks montrent le même graphe. Chaque bloc utilise block <étiquette> <type> <X> <Y>, puis value et link, terminé par end. trace true active son journal. Appliquer le code valide tout avant de modifier le graphe ; une erreur conserve l’ancien.|Bloques y Código Kliker Blocks muestran el mismo grafo. Cada bloque usa block <etiqueta> <tipo> <X> <Y>, luego value y link, y termina con end. trace true activa su registro. Aplicar código valida todo antes de cambiar el grafo; un error conserva el anterior.|“块”和“Kliker Blocks 代码”显示同一连接图。每块以 block <标签> <类型> <X> <Y> 开始，后接 value、link，以 end 结束。trace true 启用日志。应用代码会先验证全文，出错时保留原图。
Переменные и массивы|Les noms de variables/tableaux utilisent A–Z, a–z, 0–9 et _, avec une lettre ou _ au début ; la casse est ignorée. ${counter} insère une valeur dans un champ ; =($counter+2)*3 calcule une expression. Les tableaux commencent à l’indice 0. Les valeurs sont partagées entre branches et sous-programmes pendant une exécution, conservées entre passages répétitifs mais réinitialisées au prochain lancement. Évitez des écritures parallèles sur le même nom.|Los nombres de variables y matrices solo usan A–Z, a–z, 0–9 y _, empezando por letra o _; no distinguen mayúsculas. ${counter} inserta un valor en un campo; =($counter+2)*3 calcula una expresión. Las matrices empiezan en índice 0. Los valores se comparten entre ramas y subrutinas durante una ejecución, persisten entre vueltas repetidas y se reinician en la siguiente ejecución. Evite escrituras paralelas al mismo nombre.|变量和数组名仅可用英文字母、数字和下划线，且以字母或下划线开头；不区分大小写。${counter} 插入变量值，=($counter+2)*3 计算表达式。数组索引从 0 开始。一次运行中的分支和子程序共享变量；重复轮次保留变量，下次运行重新初始化。避免并行修改同名变量。
Журнал и запись в файл|La case Journaliser les actions du bloc ajoute son nom, son identifiant et la sortie choisie au journal. Le menu Scénario crée le journal complet UTF-8 .txt/.log au lancement, près du projet enregistré ou de l’application si le projet n’est pas enregistré ; le chemin complet est affiché. Limite : 8 Mio, les lancements suivants ajoutent des lignes. Le bloc Fichier journal crée son fichier dès son exécution, mais ne copie que les messages explicites. Ne journalisez pas de secrets.|La casilla Registrar acciones del bloque añade su nombre, ID y salida elegida al registro. El menú Escenario crea el registro completo UTF-8 .txt/.log al iniciar, junto al proyecto guardado o junto a la aplicación si aún no se guardó; muestra la ruta completa. Límite: 8 MiB; ejecuciones posteriores añaden líneas. El bloque Archivo de registro crea su archivo al ejecutarse, pero solo copia mensajes explícitos. No registre secretos.|勾选“记录块操作”会将块名、标识和所选输出写入日志。“场景”菜单会在运行时创建完整的 UTF-8 .txt/.log 日志：已保存项目放在项目旁，未保存项目放在程序旁，并显示完整路径。上限 8 MiB，后续运行会追加。“日志文件”块执行时立即创建文件，但只复制显式消息。不要记录密码或令牌。
Снимки и образы|Le menu Capture enregistre un point ou une zone d’écran et ouvre la bibliothèque. Choisissez la forme de zone lors de la capture. Dans les blocs de recherche d’image, sélectionnez un modèle, des limites et une tolérance ; les coordonnées trouvées sont réutilisables.|El menú Captura guarda un punto o área de pantalla y abre la biblioteca. Elija la forma al capturar. En los bloques de búsqueda de imagen seleccione plantilla, límites y tolerancia; luego puede usar las coordenadas encontradas.|“截图”菜单可保存坐标点、捕获屏幕区域并打开素材库。捕获时选择区域形状。图像搜索块可指定模板、范围和容差；找到的坐标可供后续块使用。
Запись макросов|Le menu Macro offre l’enregistrement complet des actions ou des clics avec modèles d’image. Le panneau d’enregistrement permet pause, reprise et arrêt. Enregistrez le résultat dans la bibliothèque puis convertissez-le en blocs modifiables.|El menú Macro ofrece grabación completa de acciones o de clics con plantillas de imagen. El panel permite pausar, reanudar y detener. Guarde el resultado en la biblioteca y conviértalo en bloques editables.|“宏”菜单可完整录制操作，或只录制点击并附带图像模板。录制面板支持暂停、继续和停止。录制结果可存入素材库并转换为可编辑的块。
Слежение за курсором|Surveiller le curseur peut agir immédiatement, basculer par une touche ou fonctionner tant qu’elle est maintenue. Une touche ou un bouton de souris supplémentaire peut être exigé. Réglez le point d’ancrage, le seuil, la destination, la fréquence de contrôle et le délai. Certains programmes traitent les entrées de souris différemment ; aucun contournement de protection n’est fourni.|Vigilar cursor puede empezar de inmediato, alternar con una tecla o funcionar mientras se mantenga. Puede exigir otra tecla o botón del ratón. Configure ancla, umbral, destino, frecuencia de revisión y retraso. Algunas aplicaciones procesan el ratón de otra forma; no se ofrece elusión de protecciones.|“监视光标”可立即工作、由按键切换，或仅在按住按键时工作；还可要求额外按键或鼠标键。可设置基准点、位移阈值、返回目标、检查间隔和延迟。不同程序对鼠标输入的处理不同；不提供保护绕过功能。
